/* Original CC0-1.0: retain the project's licensed brand font if present. */
body { font-family: var(--brand-font, system-ui), sans-serif; line-height: 1.5; }
.page-title { font-size: clamp(1.75rem, 1.2rem + 2vw, 2.5rem); font-weight: 500; line-height: 1.15; }
.prose { max-inline-size: 65ch; }
.amount { font-variant-numeric: tabular-nums; text-align: end; }
.meta { font-size: .875rem; letter-spacing: 0; }

/* Original CC0-1.0 responsive app shell. */
.app-shell { display: grid; grid-template-columns: 16rem minmax(0, 1fr); min-block-size: 100dvh; }
.app-main { min-inline-size: 0; padding: clamp(1rem, 3vw, 2rem); }
.task-list { display: grid; gap: .5rem; }
.task-row { display: grid; grid-template-columns: 1.25rem minmax(0, 1fr) auto; gap: .75rem; align-items: center; padding: .75rem 0; border-block-end: 1px solid var(--border); }
@media (max-width: 48rem) { .app-shell { grid-template-columns: minmax(0, 1fr); } }

/* Independently authored CC0-1.0 palette; check contrast in the final screen. */
:root { --page: #f8f5ef; --surface: #ffffff; --text: #25211c; --secondary: #625a50; --border: #b9b0a4; --accent: #7b3b16; }
body { background: var(--page); color: var(--text); }
.primary-action { color: #fff; background: var(--accent); border: 1px solid var(--accent); }
.secondary-copy { color: var(--secondary); }
:where(button, a, input, select, textarea):focus-visible { outline: 3px solid var(--accent); outline-offset: 3px; }

/* Original CC0-1.0: meaningful copy first in the DOM, local preview second. */
.hero { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, .9fr); gap: clamp(1.5rem, 5vw, 4rem); align-items: center; padding-block: clamp(2rem, 7vw, 5rem); }
.hero-copy { max-inline-size: 36rem; }
.hero-preview { min-inline-size: 0; background: var(--surface); border: 1px solid var(--border); border-radius: 1rem; padding: 1.5rem; }
@media (max-width: 48rem) { .hero { grid-template-columns: minmax(0, 1fr); } }

/* Original CC0-1.0: no loop, no catch-all transition. */
.action { transition: background-color 150ms ease-out, border-color 150ms ease-out, transform 150ms ease-out; }
.action:active { transform: scale(.98); }
.notice { animation: notice-in 180ms ease-out both; }
@keyframes notice-in { from { opacity: 0; transform: translateY(.25rem); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .action { transition: none; } .action:active { transform: none; } .notice { animation: none; } }

/* Original CC0-1.0; React must already be part of the project. */
import { useId } from 'react';
export function BalanceSummary({ amount, currency, locale }) {
  const titleId = useId();
  const formatter = new Intl.NumberFormat(locale, { style: 'currency', currency });
  return <section aria-labelledby={titleId}>
    <h2 id={titleId}>Outstanding balance</h2>
    <p className="amount">{formatter.format(amount)}</p>
    <p>Invoices awaiting payment</p>
  </section>;
}

/* Original CC0-1.0 native disclosure; React is supplied by the project. */
import { useId, useState } from 'react';
export function InvoiceDetails({ children }) {
  const panelId = useId();
  const [open, setOpen] = useState(false);
  return <section>
    <button type="button" aria-expanded={open} aria-controls={panelId} onClick={() => setOpen(value => !value)}>
      {open ? 'Hide invoice details' : 'Show invoice details'}
    </button>
    <div id={panelId} hidden={!open}>{children}</div>
  </section>;
}

/* Original CC0-1.0; use the project's existing React runtime. */
import { useId } from 'react';
export function AppointmentSummary({ dateLabel, serviceLabel, bookingHref }) {
  const titleId = useId();
  return <section className="booking-summary" aria-labelledby={titleId}>
    <h2 id={titleId}>Your appointment</h2>
    <dl><dt>Service</dt><dd>{serviceLabel}</dd><dt>Date</dt><dd>{dateLabel}</dd></dl>
    <a className="primary-action" href={bookingHref}>Review appointment</a>
  </section>;
}

/* Original CC0-1.0 companion layout; no external fonts or motion required. */
.booking-summary { max-inline-size: 38rem; padding: 1.5rem; border: 1px solid var(--border, #a59b8e); border-radius: .75rem; }
.booking-summary h2 { margin-block: 0 1rem; font-size: 1.5rem; font-weight: 500; }
.booking-summary dl { display: grid; grid-template-columns: minmax(5rem, 1fr) minmax(0, 2fr); gap: .5rem 1rem; }
.booking-summary dd { margin: 0; overflow-wrap: anywhere; }
.booking-summary .primary-action { display: inline-flex; align-items: center; min-block-size: 2.75rem; margin-block-start: 1rem; padding-inline: 1rem; }
@media (max-width: 25rem) { .booking-summary dl { grid-template-columns: minmax(0, 1fr); } .booking-summary dd { margin-block-end: .5rem; } }
